package com.qqmu.jync.service.tls;

import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.security.GeneralSecurityException;
import java.security.KeyStore;
import java.security.PrivateKey;
import java.security.cert.X509Certificate;

/**
 * One certificate chain and its private key, read from the PEM files an operator already has.
 *
 * <p>Tomcat cannot serve PEM files directly, so the pair is wrapped in a PKCS#12 keystore here.
 * The wrapping passphrase is generated by Jync and never shown; it is stored encrypted in the
 * sidecar exactly like a passphrase typed into the form. The private key therefore never reaches
 * the disk in its PEM (plaintext) form.
 */
record PemKeyPair(X509Certificate[] chain, PrivateKey key) {

    /** The alias Tomcat will serve; the page shows it as-is. */
    static final String ALIAS = "jync";

    byte[] toPkcs12(char[] passphrase) {
        try {
            KeyStore store = KeyStore.getInstance("PKCS12");
            store.load(null, passphrase);
            store.setKeyEntry(ALIAS, key, passphrase, chain);
            ByteArrayOutputStream out = new ByteArrayOutputStream();
            store.store(out, passphrase);
            return out.toByteArray();
        } catch (GeneralSecurityException | IOException e) {
            // The provider message can quote key material; only the key ships to the page.
            throw new TlsKeystoreException("error.tls.saveFailed", e);
        }
    }
}
